 const memo=[]; if(k.clMove) memo.push([AM,'CLUTCH']); if(s.master&&!k.altOn&&s.run) memo.push([AM,'ALT']); if(s.run&&s.rpm>=101&&s.nr>=101) memo.push([G,'RPM VERT']); if(s.rbrake&&s.nr>20) memo.push([RD,'FREIN ROTOR']);
