function on(s,id,v,prev){ if(id==='key'&&v==='START'){ if(s.master&&!s.run) s.crank=s.clutch?0.8:2.5; else s.key='BOTH'; } if(id==='rbrake'&&v===true&&s.nr>20){ s.rbrake=false; s._rb=1; } else if(id==='rbrake') s._rb=0; }
function ex(id,s,d){ const k=d.k, o={ln:[]}, ln=(c,t)=>o.ln.push([c,t]), blk=(t,go)=>{ o.blk=t; o.go=go; };
 switch(id){
 case 'master': o.h='Batterie'; ln('el','Le relais de batterie alimente la barre : démarreur, instruments, actionneur d\'embrayage, feux.'); ln('ig','Remarque : l\'allumage n\'en dépend pas ! Les magnétos produisent elles-mêmes le courant des bougies.'); if(!s.master&&s.run) ln('ig','Le moteur continue de tourner, batterie coupée : seules les magnétos l\'allument.'); break;
 case 'alt': o.h='Alternateur'; ln('me','Entraîné par courroie par le moteur.'); ln('el','Il recharge la batterie et alimente le circuit quand le moteur tourne.'); if(!s.run) blk('Moteur arrêté : aucun courant produit.','key'); break;
 case 'fv': o.h='Robinet carburant'; ln('fu','Les deux réservoirs (principal et auxiliaire) alimentent le moteur ; une pompe mécanique entraînée par le moteur, et une pompe auxiliaire électrique, fournissent la pression d\'injection.'); break;
 case 'auxp': o.h='Pompe auxiliaire carburant'; ln('fu','Pompe électrique : pression carburant pour le démarrage (moteur à injection), puis secours de la pompe mécanique.'); if(!s.master) blk('Batterie OFF : la pompe ne tourne pas.','master'); break;
 case 'hyd': o.h='HYD — Servocommandes'; ln('hg','La pompe hydraulique est entraînée par la boîte de transmission : elle alimente trois servocommandes qui déplacent le plateau cyclique (pas de servo au rotor anticouple).'); ln('me',s.hyd?'ON : efforts très faibles au cyclique et au collectif.':'OFF : commandes directes, efforts plus importants (exercice de panne hydraulique).'); break;
 case 'mix': o.h='Mélange'; ln('fu',s.mix==='RICH'?'RICHE : le servo d\'injection dose l\'essence envoyée aux injecteurs de chaque cylindre.':'ÉTOUFFOIR : plus d\'essence, le moteur s\'arrête (procédure d\'arrêt normale).'); break;
  case 'key': o.h='Clé de contact (magnétos)'; if(s.key==='START'||k.cranking){ if(!s.master){ blk('Batterie OFF : le démarreur ne tourne pas.','master'); break; } ln('el','START : le démarreur électrique entraîne le vilebrequin.'); ln('ig','Les magnétos, entraînées par le moteur, produisent les étincelles (2 bougies par cylindre).'); if(!k.fuel) blk('Pas de pression carburant : robinet ON, pompe auxiliaire ON et mélange RICHE.','auxp'); if(s.clutch) blk('Embrayage engagé : le démarreur doit aussi lancer le rotor, beaucoup trop lourd. On démarre toujours DÉBRAYÉ.','clutch'); }
  else if(s.key==='OFF') ln('ig','OFF : les magnétos sont mises à la masse, plus d\'étincelle, le moteur s\'arrête.'); else ln('ig',s.key==='BOTH'?'BOTH : les deux magnétos, fonctionnement normal.':`Une seule magnéto (${s.key}) : test avant vol, légère chute de régime attendue.`); break;
 case 'clutch': o.h='Embrayage (clutch actuator)'; ln('el','Un moteur électrique fait descendre la poulie inférieure : les courroies se tendent progressivement (voyant CLUTCH allumé tant qu\'il bouge).'); ln('me','La puissance du moteur passe alors par les courroies à la poulie supérieure, la roue libre, la boîte de transmission et le rotor.');
  if(!s.master) blk('Batterie OFF : l\'actionneur ne bouge pas.','master'); else if(s.clutch&&!s.run) ln('me','Moteur arrêté : les courroies se tendent mais rien ne tourne.'); break;
 case 'gov': o.h='Régulateur'; ln('dat','Un petit calculateur agit sur la poignée des gaz pour garder le régime à 102 %, le pilote n\'a presque rien à corriger.'); break;
 case 'thr': o.h='Poignée des gaz'; ln('me','Tournante, sur le collectif : câble vers le papillon d\'air du servo d\'injection (le moteur IO-540 du Raven II est à injection : pas de carburateur).'); break;
 case 'rbrake': o.h='Frein rotor'; ln('me','Frein à câble sur la transmission.'); if(s._rb) blk('Interdit avec le rotor encore rapide (au-dessus de quelques pourcents) : attendre son ralentissement après l\'arrêt.'); break;
 case 'coll': o.h='Collectif'; ln('me','Change le pas des deux pales ensemble, par des tiges et les servocommandes hydrauliques.'); if(s.coll&&!s.gov) blk('Régulateur sur OFF ou régime pas au vert : on ne décolle pas.','gov'); break;
 case 'cyc': o.h='Cyclique en T'; ln('me','Tiges et renvois vers le plateau cyclique : le disque rotor s\'incline.'); break;
 case 'ped': o.h='Palonnier'; ln('me','Câbles vers le pas du rotor anticouple.'); break;
 case 'nav': case 'acol': o.h=id==='nav'?'Feux de navigation':'Anticollision'; ln('lt',id==='nav'?'Rouge à gauche, vert à droite, blanc à l\'arrière.':'Feu rouge à éclats.'); break;
 case 'ground': o.h='Situation'; ln('me',s.ground?'Au sol.':'En vol.'); break; }
 return o; }
const tours={start:{n:'Démarrage et embrayage',st:[['master',true,'Batterie ON.'],['fv',true,'Robinet carburant ouvert.'],['auxp',true,'Pompe auxiliaire : pression d\'injection.'],['mix','RICH','Mélange riche.'],['acol',true,''],['clutch',false,'Vérifier : DÉBRAYÉ.'],['rbrake',false,'Frein rotor desserré.'],['key','START','Démarreur, puis les magnétos allument le moteur (jaune).',s=>s.run,'Attendre le moteur'],['alt',true,'Alternateur : il recharge la batterie (le courant change de sens).'],['clutch',true,'Embrayage : l\'actionneur tend les courroies, le rotor commence à tourner.',s=>s.cl>=1,'Attendre la fin de l\'embrayage'],['gov',true,'Régulateur ON : régime 102 %.',s=>s.nr>=99,'Attendre le régime'],['coll',1,'Décollage.']]}};
